Output10Using Bottom-Up DP (Tabulation) - O(n * k) Time and O(n * k) SpaceThe approach is similar to the previous one. just instead of breaking down the problem recursively, we iteratively build up the solution by calculating in bottom-up manner. Maintain a dp[][] table such that dp[i][j] stores the count all unique possible paths to reach the cell (i, j).Base Case:For i = j and  0 <= i <= n , dp[i][j] = 1  for j = 0  and  0 <= j <= min(i, k) , dp[i][j] = 1Recursive Case: For i > 1 and j > 1 ,  dp[i][j] = dp[i-1][j-1] + dp[i-1][j]
            C++

    // C++ implementation to find 
// Binomial Coefficient using tabulation

#include <bits/stdc++.h>
using namespace std;

// Returns value of Binomial Coefficient C(n, k)
int binomialCoeff(int n, int k) {
  	vector<vector<int>> dp(n + 1, vector<int> (k + 1));

    // Calculate value of Binomial Coefficient
    // in bottom up manner
    for (int i = 0; i <= n; i++) {
        for (int j = 0; j <= min(i, k); j++) {

            // Base Cases
            if (j == 0 || j == i)
                dp[i][j] = 1;

            // Calculate value using previously
            // stored values
            else
                dp[i][j] = dp[i - 1][j - 1] + dp[i - 1][j];
        }
    }

    return dp[n][k];
}

